
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_ol2_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_ol2", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([9.457479610733427e+01, 9.089674887434363e+01, 8.586776238616135e+01, 7.914217072996448e+01, 7.042817268333846e+01, 5.963723450614213e+01, 4.710629989371638e+01, 3.381805588047911e+01, 2.140975308194378e+01, 1.165902296939463e+01, 5.361261416310374e+00, 2.554688295935650e+00, 1.919468067197077e+00, 1.273301181097631e+00, 6.501695345022441e-01, 2.686050331692212e-01, 1.166700052952976e-01, 7.626490092997802e-02, 6.724814236781426e-02, 6.381899302930268e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


